create extension if not exists pgtap with schema extensions;
\i helpers/seed_members.sql
begin;
select plan(12);
select tests_seed_user('a5000000-0000-0000-0000-000000000001','p5-owner@test.local','P5 owner');
select tests_seed_user('a5000000-0000-0000-0000-000000000002','p5-member@test.local','P5 member');
select tests_seed_user('a5000000-0000-0000-0000-000000000055','p5-over-limit@test.local','P5 over limit');
select tests_seed_group('a5000000-0000-0000-0000-000000000011','P5 group one','a5000000-0000-0000-0000-000000000001','Africa/Cairo','P5ABCDEF');
select tests_seed_group('a5000000-0000-0000-0000-000000000012','P5 group two','a5000000-0000-0000-0000-000000000002','Africa/Cairo','P5ABCDEG');
select tests_seed_group('a5000000-0000-0000-0000-000000000013','P5 group three','a5000000-0000-0000-0000-000000000002','Africa/Cairo','P5ABCDEH');
select tests_seed_member('a5000000-0000-0000-0000-000000000011'::uuid,'a5000000-0000-0000-0000-000000000001'::uuid,1::smallint,'owner'::public.group_role);
select tests_seed_member('a5000000-0000-0000-0000-000000000012'::uuid,'a5000000-0000-0000-0000-000000000001'::uuid,1::smallint);
select set_config('request.jwt.claims',json_build_object('sub','a5000000-0000-0000-0000-000000000001','role','authenticated')::text,true);
select throws_ok('select public.create_group(''P5 third group'','''',''Africa/Cairo'',''00:00'',''private'',''approval'')','P0001','membership_limit','third active membership is refused');
select is((select count(*)::int from public.group_memberships where user_id='a5000000-0000-0000-0000-000000000001' and status='active'),2,'fixture has two active memberships');
update public.groups set status='archived' where id='a5000000-0000-0000-0000-000000000012';
select lives_ok('select public.create_group(''P5 after archive'','''',''Africa/Cairo'',''00:00'',''private'',''approval'')','archived membership does not count');
select tests_seed_group('a5000000-0000-0000-0000-000000000014','P5 limit target','a5000000-0000-0000-0000-000000000002','Africa/Cairo','P5ABCDQ2');
select tests_seed_group('a5000000-0000-0000-0000-000000000015','P5 existing one','a5000000-0000-0000-0000-000000000002','Africa/Cairo','P5ABCDQ3');
select tests_seed_group('a5000000-0000-0000-0000-000000000016','P5 existing two','a5000000-0000-0000-0000-000000000002','Africa/Cairo','P5ABCDQ4');
select tests_seed_group('a5000000-0000-0000-0000-000000000017','P5 existing three','a5000000-0000-0000-0000-000000000002','Africa/Cairo','P5ABCDQ5');
select tests_seed_member('a5000000-0000-0000-0000-000000000015'::uuid,'a5000000-0000-0000-0000-000000000055'::uuid,2::smallint);
select tests_seed_member('a5000000-0000-0000-0000-000000000016'::uuid,'a5000000-0000-0000-0000-000000000055'::uuid,2::smallint);
select tests_seed_member('a5000000-0000-0000-0000-000000000017'::uuid,'a5000000-0000-0000-0000-000000000055'::uuid,2::smallint);
select is((select count(*)::int from public.group_memberships where user_id='a5000000-0000-0000-0000-000000000055' and status='active'),3,'pre-existing over-limit memberships are preserved');
update public.groups set visibility='public',join_mode='auto_accept' where id='a5000000-0000-0000-0000-000000000013';
select throws_ok('select public.join_group(''a5000000-0000-0000-0000-000000000013'',null,''discovery'')','P0001','membership_limit','third discovery membership is refused');
select throws_ok('select public.join_group(null,''P5ABCDQ2'',''invite'')','P0001','membership_limit','third invite membership is refused');
select throws_ok('select public.join_any_group(''Africa/Cairo'')','P0001','membership_limit','join-any refuses third membership');
insert into public.join_requests(id,group_id,user_id,status,source) values ('a5000000-0000-0000-0000-000000000015','a5000000-0000-0000-0000-000000000014','a5000000-0000-0000-0000-000000000001','pending','discovery');
select set_config('request.jwt.claims',json_build_object('sub','a5000000-0000-0000-0000-000000000002','role','authenticated')::text,true);
select throws_ok('select public.review_join_request(''a5000000-0000-0000-0000-000000000015'',''approve'')','P0001','membership_limit','approval refuses third active membership');
select is((select count(*)::int from public.group_memberships where user_id='a5000000-0000-0000-0000-000000000001' and status='active' and group_id in ('a5000000-0000-0000-0000-000000000011','a5000000-0000-0000-0000-000000000012')),2,'existing memberships remain intact after limit refusal');
select is((select status::text from public.join_requests where id='a5000000-0000-0000-0000-000000000015'),'pending','refused approval preserves the pending request');
select set_config('request.jwt.claims',json_build_object('sub','a5000000-0000-0000-0000-000000000001','role','authenticated')::text,true);
select is(public.get_invite_preview('P5ABCDQ2')->>'can_join_limit','false','invite preview reports caller at membership limit');
insert into public.group_memberships(group_id,user_id,role,status,seat_number) values ('a5000000-0000-0000-0000-000000000013','a5000000-0000-0000-0000-000000000001','member','left',null);
select is(public.active_membership_count('a5000000-0000-0000-0000-000000000001'),2,'left and archived memberships do not count');
select * from finish();
rollback;
